  'inconcertta.offer.rightTitle': tr('Pensée pour les acteurs publics', 'Designed for public-sector actors', 'Pensada para los actores públicos', 'Pensata per gli attori pubblici'),
  'inconcertta.offer.rightLead': tr('La solution s’adresse notamment à&nbsp;:', 'The solution is aimed in particular at:', 'La solución se dirige en particular a:', 'La soluzione si rivolge in particolare a:'),
  'inconcertta.offer.rightItem1': tr('les <strong>collectivités</strong> (communes, intercommunalités, régions) ;', 'local <strong>authorities</strong> (municipalities, inter-municipal bodies, regions);', 'las <strong>administraciones locales</strong> (municipios, intercomunidades, regiones);', 'gli <strong>enti locali</strong> (comuni, intercomunalità, regioni);'),
  'inconcertta.offer.rightItem2': tr('les <strong>cabinets</strong> d’urbanisme et de concertation ;', 'urban planning and consultation <strong>consultancies</strong>;', 'los <strong>gabinetes</strong> de urbanismo y concertación;', 'gli <strong>studi</strong> di urbanistica e concertazione;'),
  'inconcertta.offer.rightItem3': tr('les <strong>porteurs</strong> de projets territoriaux.', 'leaders of territorial projects.', 'los <strong>promotores</strong> de proyectos territoriales.', 'i <strong>promotori</strong> di progetti territoriali.'),
  'inconcertta.offer.formulaIntro': tr('Plusieurs <strong>modalités commerciales</strong> sont possibles&nbsp;:', 'Several <strong>commercial options</strong> are possible:', 'Son posibles varias <strong>modalidades comerciales</strong>:', 'Sono possibili diverse <strong>modalità commerciali</strong>:'),
  'inconcertta.offer.formula1': tr('<strong>Service — accès à la plateforme</strong> pour vos concertations, en <strong>ponctuel</strong> (durée d’un dispositif) ou en usage <strong>récurrent</strong> sur la durée.', '<strong>Service - access to the platform</strong> for your consultations, either <strong>one-off</strong> (for the duration of a scheme) or <strong>recurring</strong> over time.', '<strong>Servicio — acceso a la plataforma</strong> para sus concertaciones, de forma <strong>puntual</strong> (duración de un dispositivo) o en uso <strong>recurrente</strong> en el tiempo.', '<strong>Servizio — accesso alla piattaforma</strong> per le vostre concertazioni, in modalità <strong>occasionale</strong> (durata di un dispositivo) o in uso <strong>ricorrente</strong> nel tempo.'),
  'inconcertta.offer.formula2': tr('<strong>Offre personnalisée</strong> — charte graphique, paramétrage et accompagnement au montage.', '<strong>Custom offer</strong> - branding, configuration and setup support.', '<strong>Oferta personalizada</strong> — carta gráfica, parametrización y acompañamiento en la puesta en marcha.', '<strong>Offerta personalizzata</strong> — identità grafica, parametrizzazione e accompagnamento alla messa a punto.'),
  'inconcertta.offer.formula3': tr('<strong>Instance dédiée (white-label)</strong> — identité propre, base isolée, services associés.', '<strong>Dedicated instance (white-label)</strong> - own identity, isolated database, associated services.', '<strong>Instancia dedicada (white-label)</strong> — identidad propia, base aislada, servicios asociados.', '<strong>Istanza dedicata (white-label)</strong> — identità propria, base isolata, servizi associati.'),
  'inconcertta.offer.includes': tr('Chaque formule peut inclure :', 'Each package can include:', 'Cada fórmula puede incluir:', 'Ogni formula può includere:'),
  'inconcertta.offer.include1': tr('le déploiement technique de la plateforme', 'technical deployment of the platform', 'el despliegue técnico de la plataforma', 'il deploy tecnico della piattaforma'),
  'inconcertta.offer.include2': tr('la prise en main et la formation des équipes', 'onboarding and team training', 'la toma en mano y la formación de los equipos', 'presa in carico e formazione dei team'),
  'inconcertta.offer.include3': tr('l’accompagnement à l’animation des démarches', 'support for facilitating the process', 'el acompañamiento a la dinamización de los procesos', 'l’accompagnamento nell’animazione dei percorsi'),

  'inconcertta.incitta.title': tr('InCitta & InConcertta', 'InCitta & InConcertta', 'InCitta e InConcertta', 'InCitta e InConcertta'),
